import{_ as t,o as s,c as e,ag as a}from"./chunks/framework.DHSXpJLs.js";const k=JSON.parse('{"title":"IFC 编辑 API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/edit-api.md","filePath":"reference/edit-api.md","lastUpdated":1790779354000}'),d={name:"reference/edit-api.md"};function o(l,i,n,h,p,r){return s(),e("div",null,[...i[0]||(i[0]=[a(`<h1 id="ifc-编辑-api" tabindex="-1">IFC 编辑 API <a class="header-anchor" href="#ifc-编辑-api" aria-label="Permalink to &quot;IFC 编辑 API&quot;">​</a></h1><p>edit-service 是 IFC 编辑端点的唯一参考，Python FastAPI，默认端口 8100。路径参数 <code>id</code> 匹配 <code>^m_[0-9a-f]{16}$</code>，<code>guid</code> 是 IFC GlobalId。直连时错误响应是 FastAPI 形态的 <code>{&quot;detail&quot;: ...}</code>，经 Go 代理时换成 envelope（见文末）。</p><p>定位、暂存、大版本这些概念与版本语义见<a href="/SourceAEC/guide/editing">编辑与版本</a>，本页只讲契约。DXF 侧端点为同一套，差异见 <a href="/SourceAEC/development/cad-service">CAD 编辑服务</a>。</p><blockquote><p>直改链路已于 2026-08-08 退役：直连本服务返回 410 Gone（不是 404），经 Go 代理的对应路由已注销、返回 404。修改一律走构建脚本。历史实现可从 git 历史回捞，锚点 <code>fb55a8a</code>——当时的路径是 <code>viewer/edit-service/app/routes_edits.py</code>，后随目录重组迁到 <code>services/ifc/</code> 下。</p></blockquote><h2 id="构建脚本契约" tabindex="-1">构建脚本契约 <a class="header-anchor" href="#构建脚本契约" aria-label="Permalink to &quot;构建脚本契约&quot;">​</a></h2><p>每个模型对应一个完整 Python 脚本，必须满足：</p><ul><li>头部 <code>PARAMS = {...}</code> 是顶层字面量 dict，所有可调参数集中在这里。</li><li>构件的 GlobalId 由 key 确定性派生，并写入 <code>Pset_AIIFC.designKey</code>。同一脚本跑多少次 id 都不变，跨版本 diff 才能对齐。</li><li>审查可见的构件必须经契约工厂 <code>script_lib.create_entity</code> 创建，工厂自动写确定性身份并记录调用点。禁止绕过工厂直接建实体。</li><li>需要 web 表单可编辑的参数必须是标量字面量或 PARAMS 引用，不能是任意表达式，否则定向改写会拒绝。</li><li>入口是 <code>build(params, out_path)</code>，产物必须过 <code>ifcopenshell.validate</code>。</li></ul><h2 id="脚本编辑端点" tabindex="-1">脚本编辑端点 <a class="header-anchor" href="#脚本编辑端点" aria-label="Permalink to &quot;脚本编辑端点&quot;">​</a></h2><p><code>GET</code>、<code>PUT</code> 与 undo/redo 走暂存语义，<code>run</code> 沙箱试运行不产生版本，<code>save</code> 晋升大版本。</p><table tabindex="0"><thead><tr><th>端点</th><th>语义</th></tr></thead><tbody><tr><td><code>GET /models/{id}/script</code></td><td>当前脚本，暂存态优先，否则最近保存的版本</td></tr><tr><td><code>PUT /models/{id}/script</code></td><td>暂存一次编辑，整体替换脚本或只改 PARAMS。plain 模型首次暂存自动保留原件为 <code>bootstrap.ifc</code></td></tr><tr><td><code>GET /models/{id}/script/params</code></td><td>当前 PARAMS，ast 提取不执行脚本</td></tr><tr><td><code>POST /models/{id}/script/undo|redo|discard</code></td><td>暂存导航与放弃</td></tr><tr><td><code>POST /models/{id}/script/run</code></td><td>沙箱试运行，预览用，不产生版本</td></tr><tr><td><code>POST /models/{id}/script/save</code></td><td>晋升大版本；有 bootstrap 时响应带 alignment 计数</td></tr><tr><td><code>GET /models/{id}/scripts</code></td><td>大版本脚本列表</td></tr><tr><td><code>POST /models/{id}/script/rollback</code></td><td>恢复某版脚本并重新执行</td></tr><tr><td><code>POST /models/{id}/script/diff</code></td><td>两个大版本之间的脚本 diff</td></tr><tr><td><code>GET /models/{id}/script/staging/diff</code></td><td>暂存链相邻步之间的轻量行内 diff</td></tr><tr><td><code>GET /models/{id}/script/locate?guid=</code></td><td>guid 定位到脚本调用点，语义见下节</td></tr><tr><td><code>POST /models/{id}/script/edit-call</code></td><td>libcst 标量改写，<strong>仅直连可用</strong>。非法输入 422 零副作用</td></tr><tr><td><code>POST /models/{id}/user-edits</code></td><td>登记外部用户修改（标 <code>USER</code> 来源），不经过沙箱。IFC 侧独有，<strong>Go 代理未注册此路由</strong></td></tr></tbody></table><p><code>GET /health</code> 返回 <code>{&quot;status&quot;: &quot;ok&quot;}</code>。</p><h2 id="定位链路" tabindex="-1">定位链路 <a class="header-anchor" href="#定位链路" aria-label="Permalink to &quot;定位链路&quot;">​</a></h2><p>每次沙箱执行时，契约工厂记下每个构件的调用点，落成 map sidecar，按脚本哈希绑定发布：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ScriptMap </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dict[designKey, {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;col&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snippet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                             &quot;origin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;literal&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;params&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;traced&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 发布信封（current.map.json / v{n}.map.json）：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {&quot;scriptHash&quot;: sha256(脚本全文), &quot;map&quot;: ScriptMap}</span></span></code></pre></div><p>map 的行号只对生成它的那份脚本有效。暂存了新脚本但没运行过，两者就分叉：<code>edit-call</code> 对分叉直接拒绝（409），<code>locate</code> 降级返回 <code>stale: true</code>，前端提示先运行脚本。查不到构件返回 200 加 <code>found: false</code>，不是 5xx。</p><p><code>origin</code> 决定前端的改写策略——<code>params</code> 走参数表单，<code>literal</code> 可直接改这一行，<code>traced</code>（运行时算出来的值）只能定位不能自动改写。</p><h2 id="版本与语义对比" tabindex="-1">版本与语义对比 <a class="header-anchor" href="#版本与语义对比" aria-label="Permalink to &quot;版本与语义对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端点</th><th>语义</th></tr></thead><tbody><tr><td><code>GET /models/{id}/versions</code></td><td><code>{&quot;versions&quot;: [{&quot;version&quot;: &quot;v1&quot;, &quot;createdAt&quot;: &quot;&lt;ISO8601 UTC&gt;&quot;}, ...], &quot;current&quot;: &quot;v2&quot;}</code>。只有最新大版本的 IFC 在盘上，历史版本按需从脚本重建</td></tr><tr><td><code>POST /models/{id}/diff</code></td><td>body <code>{&quot;base&quot;: &quot;v1&quot;, &quot;target&quot;: &quot;v2&quot;}</code>，target 可为 <code>&quot;current&quot;</code></td></tr><tr><td><code>POST /models/{id}/diff/upload</code></td><td>multipart 字段 <code>file</code> 与当前状态做属性级对比。比普通 diff 多一个 <code>labels</code>（guid 到可读名称）。不落盘不缓存</td></tr><tr><td><code>GET /models/{id}/pending</code></td><td>当前 pending 列表。直改退役后仅作运行簿记，<strong>不校验模型是否存在</strong></td></tr><tr><td><code>DELETE /models/{id}/pending</code></td><td>丢弃全部 pending，返回条数；模型不存在返回 404</td></tr><tr><td><code>GET /models/{id}/history</code></td><td>持久化编辑历史，存在模型的 <code>edit-history.json</code>。直改退役后只读保留</td></tr></tbody></table><p>diff 响应形状：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;base&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;added&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;guid&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;removed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;guid&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;guid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;field&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;old&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;new&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>对比是属性级语义，不做几何对比。版本不存在返回 404，缺参数返回 422；上传对比的文件非法返回 422。</p><h2 id="经-go-代理" tabindex="-1">经 Go 代理 <a class="header-anchor" href="#经-go-代理" aria-label="Permalink to &quot;经 Go 代理&quot;">​</a></h2><p>Go server 把这些端点暴露在 <code>/api/v1</code> 下：</p><ul><li>脚本编辑端点一一对应，路径不变，query 透传。run、save、rollback 成功后自动排队重转 XKT。<code>script/edit-call</code> <strong>不经代理</strong>，仅直连可用。</li><li>只读与对比端点在 <code>edit/...</code> 前缀下：<code>edit/diff</code>、<code>edit/pending</code>、<code>edit/history</code>、<code>edit/versions</code>。</li><li>直改代理路由已随退役删除。</li></ul><p>与直连的差异：响应统一包 envelope，错误码映射为 <code>40400</code>、<code>40900</code>、<code>40001</code>、<code>50200</code> 等，见 <a href="/SourceAEC/reference/rest-api#响应与错误码">REST API</a>。</p><p>机器可读 schema 见<a href="/SourceAEC/reference/edit-api-reference">编辑 API 参考</a>，由 FastAPI 导出，与本页同源。</p>`,26)])])}const E=t(d,[["render",o]]);export{k as __pageData,E as default};
